{
  "packet_id": "H6-T01-2",
  "claim_id": "C065",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C065.component",
    "value": "Inconsistent results at the trial's end do not justify rollout.",
    "scope": "Conditional limit on deployment following trial review.",
    "provenance": {
      "refs": [
        {
          "source_id": "P033",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly attributes further observation or revised testing, rather than rollout, to inconsistent trial results."
    }
  },
  "signal_basis": {
    "component_id": "C065.signal_basis",
    "value": "A reduced configuration repeatedly reproduces lateness, but replay agreement does not establish field effectiveness. The subsequent field trial is reviewed against predefined comparisons and success criteria; its results are inconsistent.",
    "scope": "Evidence from the selected replay and the bounded field trial, with existing-service deadlines and operational safeguards retained.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        },
        {
          "source_id": "P030",
          "role": "SUPPORT"
        },
        {
          "source_id": "P033",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the reduction signal, its field-effectiveness limitation, the trial's predefined evaluation framework, and the conditional observation of inconsistent results."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C065.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported within its explicit bounds without an additional unresolved empirical relation."
    }
  },
  "rationale": "The replay signal establishes only test-relative reproduction. When the subsequent trial yields inconsistent results, the described evidence does not establish field effectiveness sufficient to justify rollout. The claim appropriately limits deployment without asserting that the proposed change cannot work.",
  "uncertainty": "The packet does not specify the exact pattern of inconsistency. That limits diagnosis of the trial outcome, but does not defeat this bounded restriction on what the described evidence justifies.",
  "anomalies": []
}
